    // 3. Standard ordering: M* D? C* L? X* V? I* (with subtractive pairs embedded)

    const validSubtractive = new Set(["IV", "IX", "XL", "XC", "CD", "CM"]);

    // Check for invalid subtractive pairs and count repeats
    const counts = {};
    for (let i = 0; i < input.length; i++) {
        const ch = input[i];
        counts[ch] = (counts[ch] || 0) + 1;
        // If this is a subtractive position: current < next
        if (i + 1 < input.length) {
            const next = input[i + 1];
            if (map[ch] < map[next]) {
                const pair = ch + next;
                if (!validSubtractive.has(pair)) return null;
            }
        }
    }

    // Check no more than three repeats of I, X, C, M
    // V, L, D should appear at most once
    if ((counts["I"] || 0) > 3) return null;
    if ((counts["X"] || 0) > 3) return null;
    if ((counts["C"] || 0) > 3) return null;
