  const N = BigInt(n);

  function isqrt(N) {
    if (N < 0n) throw new Error("negative");
    if (N < 2n) return N;
    let x = 1n << ((N.toString(2).length + 1) >> 1);
    while (true) {
      const y = (x + N / x) / 2n;
      if (y >= x) return x;
      x = y;
    }
  }

  function ceilSqrt(N) {
    const r = isqrt(N);
    if (r * r === N) return r;
    return r + 1n;
  }

  function gcd(a, b) {
    while (b !== 0n) {
      const t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  // Try Fermat's factorization - fast if factors are close
  let a = ceilSqrt(N);
  let b2 = a * a - N;
  let b = isqrt(b2);
  let fermatIters = 0;
  const maxFermat = 50000;

  while (b * b !== b2 && fermatIters < maxFermat) {
    a += 1n;
    b2 = a * a - N;
    b = isqrt(b2);
    fermatIters++;
  }

  if (b * b === b2) {
    const p = a - b;
    const q = a + b;
    if (p > 0n && q > 0n && p * q === N) {
      const result = [p, q].sort((x, y) => x < y ? -1 : x > y ? 1 : 0);
      return [result[0].toString(), result[1].toString()];
    }
  }

  // Brent's variant of Pollard's rho with batched GCD
  function brent(N) {
    if (N % 2n === 0n) return 2n;
    if (N % 3n === 0n) return 3n;

    let c = 1n;
    for (let attempt = 0; attempt < 30; attempt++) {
      c = BigInt(attempt + 1);
      let y = 2n;
      let r = 1n;
      let q = 1n;
      let g = 1n;
      const m = 128n;
      let x = 0n;
      let ys = 0n;

      while (g === 1n) {
        x = y;
        for (let i = 0n; i < r; i++) {
          y = (y * y + c) % N;
        }
        let k = 0n;
        while (k < r && g === 1n) {
          ys = y;
          const bound = Math.min(m, r - k);
          for (let i = 0n; i < bound; i++) {
            y = (y * y + c) % N;
            const diff = x > y ? x - y : y - x;
            q = (q * diff) % N;
          }
          g = gcd(q, N);
          k += m;
        }
        r *= 2n;
        if (r > 100000000n) break;
      }

      if (g !== N) {
        q = 1n;
        let found = false;
        for (let i = 0n; i < 100000n; i++) {
          ys = (ys * ys + c) % N;
          const diff = x > ys ? x - ys : ys - x;
          q = (q * diff) % N;
          g = gcd(q, N);
          if (g > 1n) { found = true; break; }
        }
        if (found && g !== N) return g;
      }
    }
    throw new Error("Brent failed");
  }

  const d = brent(N);
  const p = d;
  const q = N / d;
  const result = [p, q].sort((x, y) => x < y ? -1 : x > y ? 1 : 0);
  return [result[0].toString(), result[1].toString()];
}
