function solve(input) {
    const { from, to } = input;

    const parseDate = (iso) => {
        const [y, m, d] = iso.split('-').map(Number);
        return new Date(Date.UTC(y, m - 1, d));
    };

    const fromDate = parseDate(from);
    const toDate = parseDate(to);

    const msPerDay = 24 * 60 * 60 * 1000;
    const totalDays = Math.round((toDate.getTime() - fromDate.getTime()) / msPerDay);

    if (totalDays <= 0) return 0;

    // Get the day of week for from (0=Sun, 1=Mon, ..., 6=Sat)
    const fromDay = fromDate.getUTCDay();

    let count = 0;

    // For each complete week, add 5 weekdays
    const fullWeeks = Math.floor(totalDays / 7);
    count += fullWeeks * 5;

    // Remaining days
    const remainingDays = totalDays % 7;

    // Count weekdays in the remaining days starting from fromDay
    for (let i = 0; i < remainingDays; i++) {
        const day = (fromDay + i) % 7;
        if (day >= 1 && day <= 5) {
            count++;
        }
